def iter_index_new(iterable, value, start=0, stop=None):
    import operator
    from itertools import islice

    try:
        seq_index = iterable.index
    except AttributeError:
        # Slow path for general iterables
        if stop is None:
            it = islice(iterable, start, None)
        else:
            it = islice(iterable, start, stop)

        i = start - 1
        try:
            while True:
                i = i + operator.indexOf(it, value) + 1
                yield i
        except ValueError:
            pass
    else:
        # Fast path for sequences
        i = start - 1
        try:
            while True:
                i = seq_index(value, i + 1, stop)
                yield i
        except ValueError:
            pass

# Edge cases
print("Empty:", list(iter_index_new('', 'a')))  # []
print("No match:", list(iter_index_new('abc', 'x')))  # []
print("start > len:", list(iter_index_new('abc', 'a', 5)))  # []
print("stop <= start:", list(iter_index_new('abcabc', 'a', 3, 2)))  # []
print("AABCADEAF:", list(iter_index_new('AABCADEAF', 'A')))  # [0, 1, 4, 7]
